import tarfile
import os
import subprocess

def solve(primary: str, comparison: str):
    def list_tar_members_with_executable_bit(tar_path):
        try:
            result = subprocess.run(['tar', '-tf', tar_path], capture_output=True, text=True, check=True)
            members = result.stdout.splitlines()
            executable_files = []
            for member in members:
                if member.startswith('-rwx') or member.startswith('-r-x') or member.startswith('-rw-x') or member.startswith('-r--x'):
                    name = os.path.basename(member.rstrip('/'))
                    suffix = os.path.splitext(name)[1]
                    executable_files.append(suffix)
            return set(executable_files)
        except subprocess.CalledProcessError:
            raise RuntimeError(f"Failed to list members of {tar_path}")

    def list_tar_members_with_hard_links(tar_path):
        try:
            with tarfile.open(tar_path, 'r') as tar:
                hard_link_names = set()
                for member in tar.getmembers():
                    if member.issym() or member.islnk():
                        continue
                    name = os.path.basename(member.name.rstrip('/'))
                    suffix = os.path.splitext(name)[1]
                    hard_link_names.add(suffix)
                return hard_link_names
        except tarfile.TarError:
            raise RuntimeError(f"Failed to read {tar_path}")

    primary_suffixes = list_tar_members_with_hard_links(primary)
    comparison_suffixes = list_tar_members_with_executable_bit(comparison)

    result = sorted(comparison_suffixes - primary_suffixes)
    return result
